import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Color,
  Texture,
  Vector3,
  Euler,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  textureNode,
  mix,
  vec4,
  uv,
  add,
  sub,
  mul,
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { createSDFTextMaterial } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {string} [assets.depthMapUrl]
 * @property {string} [assets.meshUrl]
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {string} textContent
 * @property {{ position: [number, number, number], rotation: [number, number, number], scale: [number, number, number] }} placement
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {(url:string)=>any} glbLoader
 * @property {Object.<string, (obj:THREE.Object3D, params:any)=>void>} primitives
 * @property {Texture} fontAtlas
 */

/**
 * Creates a textured plane with MSDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ------- Background Plane -------
  const imgTex = ctx.textureLoader(config.assets.imageUrl);
  const bgMaterial = new MeshBasicNodeMaterial({
    map: textureNode(imgTex),
    transparent: true,
  });

  // Preserve aspect ratio if possible (fallback to 1:1)
  const imgWidth = imgTex.source?.data?.width ?? 1;
  const imgHeight = imgTex.source?.data?.height ?? 1;
  const aspect = imgWidth / imgHeight;
  const bgGeometry = new PlaneGeometry(1 * aspect, 1);

  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.name = 'FeaturesCardBackground';

  // ------- Text Overlay -------
  const text = config.textContent || '';
  const textMaterial = createSDFTextMaterial({
    text,
    atlas: ctx.fontAtlas,
    color: new Color('#16161d'), // ink color
    opacity: 1,
    // Using default sizing; scale will be adjusted via geometry size
  });

  const textGeometry = new PlaneGeometry(1 * aspect, 1);
  const textMesh = new Mesh(textGeometry, textMaterial);
  textMesh.name = 'FeaturesCardText';
  textMesh.position.set(0, 0, 0.001); // slightly in front of background

  // ------- Group Assembly -------
  const group = new Object3D();
  group.name = 'FeaturesCardNode';
  group.add(bgMesh);
  group.add(textMesh);

  // Apply placement
  const [px, py, pz] = config.placement?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.placement?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.placement?.scale ?? [1, 1, 1];
  group.position.set(px, py, pz);
  group.rotation.set(rx, ry, rz);
  group.scale.set(sx, sy, sz);

  // ------- Cinematic Primitives -------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        ctx.primitives[prim.name](group, prim.params);
      }
    }
  }

  // ------- Handlers (none for this node) -------
  group.userData.handlers = {};

  // ------- Cleanup ----------
  const timelines = []; // collect any GSAP timelines if created in the future
  group.userData.cleanup = () => {
    // Dispose geometry and materials
    bgGeometry.dispose();
    bgMaterial.dispose();
    textGeometry.dispose();
    textMaterial.dispose();

    // Dispose texture if it was created locally (optional)
    // imgTex.dispose(); // comment out if texture is shared globally

    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
  };

  return group;
}
